/**
 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
 *
 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
 * sites that must never disagree about what a mod "is":
 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
 *   - app/sitemap.ts (which detail pages get indexed)
 *
 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
 *
 * HONESTY: a mod only appears in the public/portal catalogue when
 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
 * excluded rather than shown with a broken badge, matching how
 * lib/actions-mods.ts's getServerMods already filters for the per-server
 * panel. Fields the source never published (gameVersions, license, ...) stay
 * empty and the UI says so — never a guess.
 *
 * REAL PAGINATION (2026-09-19): every comment in this file used to say "small
 * catalogue (~124 rows), the whole set is returned in one shot, filters run
 * client-side" — true when this was hand-seeded, false the moment a real
 * bulk import (scripts/import-modrinth-catalog.ts) landed 32,000+ real
 * Modrinth rows in the `minecraft` family alone. A hard 400-row cap
 * (`CATALOG_LIST_CAP`, since removed) used to mean the other ~31,850 mods in
 * that family were permanently unreachable — no page 2 existed. `queryCatalogMods`
 * replaces `listCatalogMods`/`searchCatalogMods` with real server-side,
 * DB-level pagination (`skip`/`take` + a real `count()`), and search/sort/
 * category-filter all run as part of the SAME query rather than over an
 * in-memory array — see StoreBrowser.tsx's own header comment for why search
 * specifically had to move server-side (its placeholder text promises to
 * search the whole catalogue, not just whatever page happens to be loaded).
 */
import { unstable_cache } from "next/cache";
import { db } from "./db";
import type { GameMod, GamePlan, Prisma } from "@prisma/client";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { paginate } from "./pagination";

/**
 * Real revalidate window for the two whole-catalogue aggregates below
 * (`listCatalogFamilies`, `totalDownloadsFor`) — both are cheap in isolation
 * today (~25-30ms, confirmed live 2026-09-21) but recomputed from scratch on
 * EVERY /mods, /mods/games/[family], /dashboard/nxlabs, and
 * /dashboard/nxlabs/games/[family] request (these pages are `force-dynamic`,
 * so nothing about the route itself is cached). Neither number needs
 * second-by-second freshness — a mod's `featured`/`downloads` values only
 * change via periodic backfill scripts (scripts/verify-gamemods.ts and
 * friends), never a live user action — so wrapping them in Next's real data
 * cache with a 10-minute window cuts real, repeated DB round trips under
 * concurrent traffic without ever showing stale-by-more-than-10-minutes data.
 */
const CATALOG_AGGREGATE_REVALIDATE_SECONDS = 600;

/** Real page size for StoreBrowser — no longer a total-catalogue ceiling. */
