function familyLabel(family: string): string {
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

type RatingAgg = { avg: number | null; count: number };

/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
  if (modIds.length === 0) return new Map();
  const rows = await db.modRating.groupBy({
    by: ["gameModId"],
    where: { gameModId: { in: modIds } },
    _avg: { rating: true },
    _count: { rating: true },
  });
  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
}

